/// Part II value types, under the names `giochi.h` uses.
///
/// The header gets `GiochiVec3` and friends from `cbindgen`'s `export.rename`; these
/// aliases give a Rust consumer of this crate the same vocabulary, so a test can read
/// like the C it stands in for. They are the very same `#[repr(C)]` types, which is why
/// asserting their size here asserts the header's layout.
pub use giochi_engine::WindowConfig as GiochiWindowConfig;
pub use giochi_engine_3d::math3d::{
    Camera3D as GiochiCamera3D, Color3D as GiochiColor3D, Quat as GiochiQuat,
    Transform3D as GiochiTransform3D, Vec3 as GiochiVec3,
};
pub use giochi_engine_3d::DirectionalLight as GiochiDirectionalLight;

/// Numeric error codes, re-exported so Rust callers do not need the engine crate.
pub use giochi_engine::error::codes;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn abi_version_matches_contract() {
        // The number `docs/C_ABI_CONTRACT.md` names as the current part. Bump it with
        // the contract, never to make a test pass.
        assert_eq!(GIOCHI_ABI_VERSION, 4);
        assert_eq!(giochi_abi_version(), GIOCHI_ABI_VERSION);
    }

    #[test]
    fn engine_version_is_packed() {
        let packed = giochi_engine_version();
        let major = (packed >> 16) & 0xFF;
        let minor = (packed >> 8) & 0xFF;
        let patch = packed & 0xFF;

        assert_eq!(
            (major, minor, patch),
            (
                giochi_engine::VERSION_MAJOR,
                giochi_engine::VERSION_MINOR,
                giochi_engine::VERSION_PATCH
            )
        );
    }

    #[test]
    fn last_error_is_empty_before_any_call() {
        // SAFETY: `giochi_get_last_error` never returns NULL and the buffer stays valid
        // until the next call on this thread; the reference is used immediately.
        let message = unsafe { std::ffi::CStr::from_ptr(giochi_get_last_error()) };
        assert_eq!(message.to_str().unwrap(), "");
    }

    #[test]
    fn a_failing_call_sets_the_message_and_the_next_call_clears_it() {
        // NULL path: reported as an invalid argument.
        assert_eq!(
            giochi_asset_size(std::ptr::null(), std::ptr::null_mut()),
            GIOCHI_ERROR_INVALID_ARGUMENT
        );
        // SAFETY: `giochi_get_last_error` never returns NULL and the buffer stays valid
        // until the next call on this thread; the reference is used immediately.
        let message = unsafe { std::ffi::CStr::from_ptr(giochi_get_last_error()) };
        assert!(message.to_str().unwrap().contains("out_size"));

        // A successful call clears it again.
        let path = std::ffi::CString::new("Cargo.toml").unwrap();
        let mut size = 0usize;
        assert_eq!(giochi_asset_size(path.as_ptr(), &mut size), GIOCHI_ERROR_OK);
        assert!(size > 0);
        // SAFETY: `giochi_get_last_error` never returns NULL and the buffer stays valid
        // until the next call on this thread; the reference is used immediately.
        let message = unsafe { std::ffi::CStr::from_ptr(giochi_get_last_error()) };
        assert_eq!(message.to_str().unwrap(), "");
    }

    #[test]
    fn calling_the_engine_before_init_reports_not_initialized() {
        assert_eq!(giochi_engine_is_running(), 0);
        assert_eq!(giochi_texture_create(std::ptr::null()), 0);
        assert_eq!(giochi_engine_run(), GIOCHI_ERROR_NOT_INITIALIZED);
        // SAFETY: `giochi_get_last_error` never returns NULL and the buffer stays valid
        // until the next call on this thread; the reference is used immediately.
        let message = unsafe { std::ffi::CStr::from_ptr(giochi_get_last_error()) };
        assert!(message.to_str().unwrap().contains("not initialised"));
    }

    #[test]
    fn unknown_handles_are_reported_not_crashing() {
        assert_eq!(giochi_scene_destroy(0), GIOCHI_ERROR_INVALID_HANDLE);
        assert_eq!(giochi_engine_run_scene(4242), GIOCHI_ERROR_INVALID_HANDLE);
        assert_eq!(giochi_texture_width(12345), 0);
    }
}
